{
  "items": [
    {
      "name": "Polynomial.as_sum_range_C_mul_X_pow",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R),\n  p = ∑ i ∈ Finset.range (p.natDegree + 1), Polynomial.C (p.coeff i) * Polynomial.X ^ i"
    },
    {
      "name": "Polynomial.sum_C_mul_X_pow_eq",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), (p.sum fun n a => Polynomial.C a * Polynomial.X ^ n) = p"
    },
    {
      "name": "Polynomial.expand_eq_sum",
      "module_name": "Mathlib.Algebra.Polynomial.Expand",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] (p : ℕ) {f : Polynomial R},\n  (Polynomial.expand R p) f = f.sum fun e a => Polynomial.C a * (Polynomial.X ^ p) ^ e"
    },
    {
      "name": "MvPolynomial.finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) →\n  [inst : CommSemiring R] → (n : ℕ) → MvPolynomial (Fin (n + 1)) R ≃ₐ[R] Polynomial (MvPolynomial (Fin n) R)"
    },
    {
      "name": "MvPowerSeries.truncFun'",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Trunc",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {R : Type u_2} → [DecidableEq σ] → [inst : CommSemiring R] → (σ →₀ ℕ) → MvPowerSeries σ R → MvPolynomial σ R"
    }
  ]
}
